contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public payable {
        require(caller != address(0), "caller zero");
        address ownerBefore = c.smartfix_owner();
        uint256 cBalanceBefore = address(c).balance;
        uint256 callerBalanceBefore = caller.balance;

        bool reverted;
        if (caller == address(this)) {
            c.sudicideAnyone();
            reverted = false;
        } else {
            (bool ok, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));
            reverted = !ok;
        }

        if (caller != address(this)) {
            assert(reverted);
            assert(c.smartfix_owner() == ownerBefore);
            assert(address(c).balance == cBalanceBefore);
            assert(caller.balance == callerBalanceBefore);
        } else {
            assert(!reverted);
        }
    }
}

