    }

    function run(bool asOwner) public payable {
        bool callerIsOwner = (asOwner && msg.sender == c.smartfix_owner()) || (!asOwner && msg.sender == c.smartfix_owner());
        require(callerIsOwner || !callerIsOwner, "tautology");

        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
